double-hashing.pseudocode:
def insert(table, key):
    m = len(table)  # 소수 크기 권장
    h1 = key % m
    h2 = 1 + key % (m - 1)  # 0이 되지 않는 탐사 간격
    for i in range(m):
        pos = (h1 + i * h2) % m
        if table[pos] is None:
            table[pos] = key
            return pos
    raise OverflowError('테이블 가득 참')

def search(table, key):
    m = len(table)
    h1, h2 = key % m, 1 + key % (m - 1)
    for i in range(m):
        pos = (h1 + i * h2) % m
        if table[pos] is None:
            return -1  # 빈 칸을 만나면 키 없음
        if table[pos] == key:
            return pos
    return -1

double-spending.pseudocode:
def validate_tx(tx, utxo, pending):
    # utxo: {출력ID: 출력}, pending: 대기 거래가 쓴 입력
    total_in = 0
    for inp in tx.inputs:
        if inp not in utxo or inp in pending:
            return False  # 이미 사용된 출력 → 이중지불
        if not verify_sig(utxo[inp], tx):
            return False
        total_in += utxo[inp].amount
    if total_in < sum(o.amount for o in tx.outputs):
        return False
    for inp in tx.inputs:
        pending.add(inp)  # 같은 입력 재사용 차단
    return True

def is_final(tx_height, tip_height, k=6):
    # k 컨펌 이후 확정으로 간주 (PoW 확률적 확정)
    return tip_height - tx_height + 1 >= k

doubly-linked-list.pseudocode:
class Node:
    def __init__(self, val):
        self.val, self.prev, self.next = val, None, None

def insert_after(lst, node, new):  # node 뒤에 new 삽입
    new.prev, new.next = node, node.next
    if node.next:
        node.next.prev = new
    else:
        lst.tail = new  # 맨 뒤에 삽입
    node.next = new

def delete(lst, node):  # 노드 참조만으로 O(1) 삭제
    if node.prev:
        node.prev.next = node.next
    else:
        lst.head = node.next  # 첫 노드 삭제
    if node.next:
        node.next.prev = node.prev
    else:
        lst.tail = node.prev  # 마지막 노드 삭제
